<?php require_once 'config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf']??null)){if(isset($_SERVER['HTTP_X_REQUESTED_WITH'])){header('Content-Type: application/json');echo json_encode(['success'=>false]);exit;}flash('error','Your cart request expired. Please try again.');redirect('cart.php');}$id=(int)($_POST['product_id']??0);$_SESSION['cart']??=[];if($_POST['action']==='add')$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+1;if($_POST['action']==='remove')unset($_SESSION['cart'][$id]);if($_POST['action']==='update')$_SESSION['cart'][$id]=max(1,(int)$_POST['quantity']);if(isset($_SERVER['HTTP_X_REQUESTED_WITH'])||str_contains($_SERVER['HTTP_ACCEPT']??'','application/json')){header('Content-Type: application/json');echo json_encode(['success'=>true,'count'=>cart_count()]);exit;}redirect('cart.php');} $items=[];$subtotal=0;try{if(!empty($_SESSION['cart'])){$ids=array_keys($_SESSION['cart']);$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=db()->prepare("SELECT * FROM products WHERE id IN ($marks)");$stmt->execute($ids);foreach($stmt as $item){$item['quantity']=$_SESSION['cart'][$item['id']];$item['line_total']=$item['quantity']*$item['price'];$subtotal+=$item['line_total'];$items[]=$item;}}}catch(Throwable $e){}$tax=$subtotal*.16;$shipping=$subtotal>=5000?0:250;$pageTitle='Your cart';include 'includes/header.php'; ?>
<section class="page-hero"><div class="container"><div class="eyebrow">Your farm basket</div><h1>Ready when<br>you are.</h1></div></section><section class="section"><div class="container cart-layout"><div><?php if(!$items): ?><div class="notice">Your cart is waiting for something good. <a class="text-link" href="shop.php">Browse the farm →</a></div><?php else: ?><table class="cart-table"><thead><tr><th>Product</th><th>Qty</th><th>Price</th><th></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><strong><?= e($item['name']) ?></strong><br><small><?= e($item['unit']) ?></small></td><td><?= (int)$item['quantity'] ?></td><td>KSh <?= number_format((float)$item['line_total']) ?></td><td><form method="post" action="cart.php"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><button class="btn btn-outline">Remove</button></form></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div><?php if($items): ?><aside class="summary"><h3>Order summary</h3><div class="summary-line"><span>Subtotal</span><span>KSh <?= number_format($subtotal) ?></span></div><div class="summary-line"><span>Tax (16%)</span><span>KSh <?= number_format($tax) ?></span></div><div class="summary-line"><span>Delivery</span><span><?= $shipping?'KSh '.number_format($shipping):'Free' ?></span></div><div class="summary-line summary-total"><span>Total</span><span>KSh <?= number_format($subtotal+$tax+$shipping) ?></span></div><a class="btn btn-primary" style="width:100%;margin-top:15px" href="checkout.php">Continue to checkout →</a></aside><?php endif; ?></div></section><?php include 'includes/footer.php'; ?>
